/**
 * composables/useOfflineMissionAnswerSync.ts
 * ---------------------------------------------------------------------------
 * [แก้ไข] คิว Offline สำหรับคำตอบด่านย่อย SINGLE_QUESTION/MULTI_QUESTION ที่ยิง
 * ไปให้ Backend ตัดสินไม่สำเร็จตอนตอบ (ไม่มีเน็ต) — เขียนตามแนวทางเดียวกับ
 * composables/useOfflineAnswerSync.ts (คิวของระบบคำถามเดิม) แต่เป็นคิว/state
 * แยกต่างหากคนละ LocalStorage key คนละ useState namespace — ไม่แตะ/ไม่เรียกใช้
 * คิวของระบบ Question เดิมเลย
 *
 * [แก้ไข — ต่างจากคิวคำถามเดิมโดยเจตนา] ระบบ Mission ใหม่ (server-gas/
 * MissionsService.gs) ไม่ส่ง correctAnswer ให้ Frontend เลยสักกรณี (sanitize
 * ออกเสมอ) — Frontend จึง "ไม่มีทางตัดสินถูก/ผิดบนเครื่องเองได้อีกต่อไป" ต่างจาก
 * ระบบคำถามเดิมที่ตัดสิน Offline First ได้ทันที คิวนี้จึงเก็บแค่ "คำตอบดิบที่ยัง
 * ไม่รู้ผล" (index หรือ array ของ index) ไว้รอยิงจริงเมื่อมีเน็ต — ด่านจะไม่ถูก mark
 * completed จนกว่าจะ sync สำเร็จและ Backend ตอบกลับมาว่าผ่านจริง (ดู
 * composables/useStationMissions.ts::submitSingleQuestion/submitMultiQuestion)
 */

export interface PendingMissionAnswer {
  clientItemId: string
  kind: 'single' | 'multi'
  stationId: string
  missionId: string
  roundId: string | null
  userId: string
  /** เฉพาะ kind: 'single' */
  answer?: number
  /** เฉพาะ kind: 'multi' */
  answers?: number[]
  queuedAt: number
}

const PENDING_KEY = 'missionAnswerSync:pendingItems'

function genUuid(): string {
  if (import.meta.client && typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID()
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
}

function readJson<T>(key: string, fallback: T): T {
  if (!import.meta.client) return fallback
  const raw = localStorage.getItem(key)
  if (!raw) return fallback
  try {
    return JSON.parse(raw) as T
  } catch {
    localStorage.removeItem(key)
    return fallback
  }
}

function writeJson(key: string, value: unknown): void {
  if (!import.meta.client) return
  localStorage.setItem(key, JSON.stringify(value))
}

export function useOfflineMissionAnswerSync() {
  const pendingItems = useState<PendingMissionAnswer[]>('mission-answer-sync-pending', () => [])
  const initialized = useState<boolean>('mission-answer-sync-initialized', () => false)
  const isSyncing = useState<boolean>('mission-answer-sync-syncing', () => false)
  const lastMessage = useState<string>('mission-answer-sync-last-message', () => '')

  const pendingCount = computed(() => pendingItems.value.length)
  const hasPending = computed(() => pendingCount.value > 0)

  function initOfflineMissionAnswerSync(): void {
    if (initialized.value) return
    pendingItems.value = readJson<PendingMissionAnswer[]>(PENDING_KEY, [])
    initialized.value = true
  }

  function persistQueue(next: PendingMissionAnswer[]): void {
    pendingItems.value = next
    writeJson(PENDING_KEY, next)
  }

  /** เรียกจาก useStationMissions.ts::submitSingleQuestion()/submitMultiQuestion()
   * ทันทีที่ยิงไปให้ Backend ตัดสินไม่สำเร็จ (ไม่มีเน็ต) — เก็บลง LocalStorage
   * รอ sync จริงทีหลัง (กันคิวซ้ำด้วย missionId+roundId — ด่านนี้ทำได้ครั้งเดียว
   * ต่อรอบอยู่แล้ว) */
  function queueMissionAnswer(item: Omit<PendingMissionAnswer, 'clientItemId' | 'queuedAt'>): void {
    if (
      pendingItems.value.some(
        (existing) => existing.missionId === item.missionId && existing.roundId === item.roundId,
      )
    ) {
      return
    }
    persistQueue([...pendingItems.value, { ...item, clientItemId: genUuid(), queuedAt: Date.now() }])
  }

  /** Sync ขึ้น Backend จริง — เรียกตอนมีเน็ต (ปุ่ม Sync มือ/auto sync ตอนกลับมามี
   * เน็ต) ยิงตาม kind ที่ค้างไว้ (submitMissionAnswer สำหรับ SINGLE_QUESTION,
   * submitMultiMission สำหรับ MULTI_QUESTION) แล้วรีเฟรชด่านย่อยของฐานนั้นจาก
   * getStationMissions ทันทีที่ sync สำเร็จ (ให้ completed/points ตรงกับ Backend
   * จริงเสมอ ไม่ประกอบผลลัพธ์เองที่นี่) */
  async function syncNow(): Promise<{ success: boolean; syncedCount: number; message: string }> {
    if (!import.meta.client || isSyncing.value) {
      return { success: false, syncedCount: 0, message: 'กำลัง Sync อยู่ หรือไม่ได้อยู่บน client' }
    }
    if (pendingItems.value.length === 0) {
      return { success: true, syncedCount: 0, message: 'ไม่มีข้อมูลที่ต้อง Sync' }
    }

    isSyncing.value = true
    try {
      const { submitMissionAnswer, submitMultiMission } = useMemberApi()
      const { loadStationMissions } = useStationMissions()
      const queue = [...pendingItems.value]
      const remaining: PendingMissionAnswer[] = []
      const stationsToRefresh = new Set<string>()
      let syncedCount = 0

      for (const item of queue) {
        try {
          const res =
            item.kind === 'single'
              ? await submitMissionAnswer({
                  missionId: item.missionId,
                  roundId: item.roundId ?? '',
                  userId: item.userId,
                  answer: item.answer ?? -1,
                })
              : await submitMultiMission({
                  missionId: item.missionId,
                  roundId: item.roundId ?? '',
                  userId: item.userId,
                  answers: item.answers ?? [],
                })
          if (res.success) {
            syncedCount += 1
            stationsToRefresh.add(item.stationId)
          } else {
            remaining.push(item)
          }
        } catch {
          remaining.push(item)
        }
      }

      persistQueue(remaining)

      for (const stationId of stationsToRefresh) {
        const item = queue.find((q) => q.stationId === stationId)
        await loadStationMissions(stationId, item?.roundId ?? null, item?.userId)
      }

      const success = remaining.length === 0
      lastMessage.value = success
        ? `Sync สำเร็จ ${syncedCount} ด่านย่อย`
        : `Sync สำเร็จ ${syncedCount} ด่านย่อย เหลือ ${remaining.length} ด่านที่ Sync ไม่สำเร็จ`

      return { success, syncedCount, message: lastMessage.value }
    } finally {
      isSyncing.value = false
    }
  }

  return {
    pendingItems: readonly(pendingItems),
    pendingCount,
    hasPending,
    isSyncing: readonly(isSyncing),
    lastMessage: readonly(lastMessage),
    initOfflineMissionAnswerSync,
    queueMissionAnswer,
    syncNow,
  }
}
/**
 * composables/useStationMissions.ts
 * ---------------------------------------------------------------------------
 * [แก้ไข] ระบบ "ด่านย่อยของฐาน" (Station Mission) เวอร์ชันจริง — ผูกกับ
 * server-gas/MissionsService.gs (ชีต "Missions"/"MissionCompletions" ของตัวเอง)
 * เต็มรูปแบบ ไม่ cross-reference กับระบบ "ภารกิจ + คำถามประจำฐาน" เดิม
 * (composables/useQuestion.ts, ชีต Questions/Answers) เลยสักจุด — ด่านย่อย
 * self-contained เนื้อคำถาม/ตัวเลือกมาในตัวเองแล้ว คำตอบเป็น index ของ options
 * (ไม่ใช่ข้อความ) Backend เป็นผู้ตัดสินถูก/ผิด+คำนวณคะแนนเพียงผู้เดียวเสมอ ไฟล์นี้
 * ไม่มีจุดไหนตัดสิน/คำนวณคะแนนเอง
 *
 * ไม่รู้จัก/ไม่แตะสิทธิ์เข้าฐาน (currentScanStationId/canEnterStation/
 * consumeScanAccess ยังอยู่ที่ composables/useStationQuest.ts เหมือนเดิม — คนละ
 * ความรับผิดชอบกัน หน้าที่ต้องใช้ Mission ต้องเรียกทั้งสอง Composable คู่กัน)
 *
 * Flow: pages/station/[stationId].vue เข้าฐาน -> loadStationMissions(stationId,
 * roundId, userId) เรียก action 'getStationMissions' (ไม่ใช่ 'listStationMissions'
 * ที่เป็น Admin-only/ไม่ sanitize) -> ได้ StationMission[] จริงจาก Backend
 * (จำนวน/ชนิดไม่ตายตัว) พร้อม completed ต่อด่าน -> ผู้เล่นทำด่าน ->
 * submitSingleQuestion()/submitMultiQuestion()/verifyQrMission() -> อัปเดต
 * State จาก response ของ Backend เท่านั้น
 *
 * Offline: Backend ไม่ส่ง correctAnswer มาให้ Frontend เลยสักกรณี (ตัดออกเสมอ —
 * ดู sanitizeMissionForPlayer_ ฝั่ง server) จึง "ไม่มีทางตัดสินถูก/ผิดบนเครื่องเอง
 * ได้อีกต่อไป" ต่างจากระบบคำถามเดิมที่ส่ง correctAnswer มาให้ตัดสิน Offline First
 * ได้ — ด่าน SINGLE_QUESTION/MULTI_QUESTION จึงทำงานแบบ "ลองยิงตรงก่อนเสมอ ยิง
 * ไม่สำเร็จ (ไม่มีเน็ตจริง ๆ) ค่อย queue ไว้รอ sync" (ดู
 * composables/useOfflineMissionAnswerSync.ts) ไม่ mark completed/แสดงผลถูก-ผิด
 * จนกว่าจะได้คำตอบจริงจาก Backend เท่านั้น (pending: true ระหว่างรอ) ส่วนภารกิจ
 * QR_SCORE ต้องมีอินเทอร์เน็ตเสมอ (ไม่มี Offline Fallback — ตรงกับ verifyStationQr
 * ที่ก็ต้องออนไลน์เหมือนกัน)
 */

import type { StationMission } from '~/types/mission'

const STORAGE_KEY = 'stationMissions:byRound'

interface StoredMissions {
  roundKey: string
  byStation: Record<string, StationMission[]>
}

/** ผลลัพธ์ที่ Component ใช้แสดงผลหลังส่งคำตอบ SINGLE_QUESTION/MULTI_QUESTION —
 * pending: true = ยังไม่รู้ผล (ไม่มีเน็ตตอนส่ง ถูก queue ไว้รอ sync จริง) ต้องรอ
 * เน็ตกลับมาก่อนถึงจะรู้ถูก/ผิด+คะแนนจริง */
export interface MissionSubmitOutcome {
  pending: boolean
  correct: boolean
  correctCount?: number
  totalQuestions?: number
  pointsAwarded: number
  alreadyCompleted: boolean
  error?: string
}

function readStored(): StoredMissions | null {
  if (!import.meta.client) return null
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw)
    if (parsed && typeof parsed.roundKey === 'string' && parsed.byStation) {
      return parsed as StoredMissions
    }
    return null
  } catch {
    return null
  }
}

function persistStored(data: StoredMissions): void {
  if (!import.meta.client) return
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
  } catch {
    // เพิกเฉย (localStorage เต็ม/Private Browsing) — เหมือนแนวทางเดียวกับ
    // composables/useStationQuest.ts::persistProgress()
  }
}

/** ล้าง Cache ด่านย่อยของฐานทั้งหมดทิ้ง (LocalStorage + State ในหน่วยความจำ) —
 * ใช้คู่กับ composables/useStationQuest.ts::clearStationQuestProgress() เสมอที่
 * 2 จุดเดียวกัน: (1) ผู้เล่นกดยืนยันรับรางวัลสำเร็จจริง หรือกด "ติดต่อเจ้าหน้าที่
 * แล้ว" ฝั่ง Offline, (2) Session หมดอายุเกิน 24 ชม. — ไม่ใช่การ Reset ตามรอบปกติ
 * (นั่นเป็นหน้าที่ของ resetForCurrentRound()/watch(effectiveRoundKey) ในไฟล์นี้
 * อยู่แล้ว) */
export function clearStationMissionsProgress(): void {
  const byStation = useState<Record<string, StationMission[]>>(
    'station-missions-by-station',
    () => ({}),
  )
  const roundKey = useState<string>('station-missions-round-key', () => 'no-round')
  byStation.value = {}
  roundKey.value = 'no-round'
  if (import.meta.client) {
    try {
      localStorage.removeItem(STORAGE_KEY)
    } catch {
      // เพิกเฉย (ดูเหตุผลเดียวกับ persistStored ด้านบน)
    }
  }
}

export function useStationMissions() {
  const byStation = useState<Record<string, StationMission[]>>(
    'station-missions-by-station',
    () => ({}),
  )
  const roundKey = useState<string>('station-missions-round-key', () => 'no-round')
  const initialized = useState<boolean>('station-missions-initialized', () => false)
  const isLoading = useState<boolean>('station-missions-loading', () => false)
  const loadError = useState<string>('station-missions-load-error', () => '')

  const { currentRoundId } = useRound()
  const { isOfflineMode, roundData } = useOfflineMode()

  /** กุญแจของ "รอบปัจจุบัน" — แนวทางเดียวกับ useStationQuest.ts::effectiveRoundKey
   * เป๊ะ ๆ (อ่านอย่างเดียว ไม่เรียกฟังก์ชันเปิด/ปิด Round ใด ๆ จากที่นี่เลย) */
  const effectiveRoundKey = computed<string>(() => {
    if (currentRoundId.value) return `online:${currentRoundId.value}`
    if (isOfflineMode.value && roundData.value?.startedAt) {
      return `offline:${roundData.value.startedAt}`
    }
    return 'no-round'
  })

  function resetForCurrentRound(): void {
    byStation.value = {}
    roundKey.value = effectiveRoundKey.value
    persistStored({ roundKey: roundKey.value, byStation: {} })
  }

  /** เรียกก่อนเสมอทุกหน้าที่ใช้ Mission (เหมือน useStationQuest.ts::
   * initStationQuest()/useQuestion.ts::initAnsweredState()) — restore Cache ของ
   * รอบปัจจุบันจาก LocalStorage (เผื่อ Hard Refresh) ก่อนจะไปเรียก
   * loadStationMissions() ของฐานใดฐานหนึ่งต่อ ไม่มีผลข้างเคียงถ้าเรียกซ้ำ */
  function initStationMissions(): void {
    if (!import.meta.client) return
    const stored = readStored()
    if (stored && stored.roundKey === effectiveRoundKey.value) {
      byStation.value = stored.byStation
    }
    roundKey.value = effectiveRoundKey.value
    initialized.value = true
  }

  // เผื่อกรณี currentRoundId/roundData เพิ่ง resolve เสร็จ "หลัง" initStationMissions()
  // ทำงานไปแล้ว (pattern เดียวกับ useStationQuest.ts/useQuestion.ts กันปัญหา
  // roundId มาช้า) — ไม่รีเซ็ตตอนเปลี่ยนเป็น 'no-round' (รอบเพิ่งจบ ยังไม่มีรอบใหม่
  // เริ่ม) ด้วยเหตุผลเดียวกับ useStationQuest.ts::watch(effectiveRoundKey)
  watch(effectiveRoundKey, (next) => {
    if (!initialized.value || roundKey.value === next) return
    if (next === 'no-round') return
    resetForCurrentRound()
  })

  function getStationMissions(stationId: string): StationMission[] {
    return byStation.value[stationId] ?? []
  }

  function missionProgressCount(stationId: string): number {
    return getStationMissions(stationId).filter((m) => m.completed).length
  }

  /** ฐานนี้ "ทำด่านย่อยครบทุกใบแล้ว" หรือยัง — false ถ้ายังไม่เคยโหลดด่านย่อยของ
   * ฐานนี้เลย (missions.length === 0) กันเข้าใจผิดว่า "ครบแล้ว" ทั้งที่ยังไม่รู้ว่ามี
   * ด่านย่อยอะไรบ้าง */
  function isStationMissionComplete(stationId: string): boolean {
    const missions = getStationMissions(stationId)
    return missions.length > 0 && missions.every((m) => m.completed)
  }

  /** คะแนนรวมที่ทำได้จริงข้ามทุกฐานที่เคยโหลดด่านย่อยมาแล้วในรอบนี้ — ใช้แสดงที่
   * pages/home.vue เป็นผลรวมที่ค่อย ๆ โตขึ้นตามฐานที่ผู้เล่นเข้าไปเล่นจริง */
  const totalPointsEarned = computed(() =>
    Object.values(byStation.value).reduce(
      (sum, missions) => sum + missions.reduce((s, m) => s + (m.completed ? m.points : 0), 0),
      0,
    ),
  )

  function setStationMissions(stationId: string, missions: StationMission[]): void {
    byStation.value = { ...byStation.value, [stationId]: missions }
    persistStored({ roundKey: roundKey.value, byStation: byStation.value })
  }

  function updateMissionFromResult(
    stationId: string,
    missionId: string,
    patch: Partial<Pick<StationMission, 'completed'>>,
  ): void {
    const missions = getStationMissions(stationId)
    const next = missions.map((m) => (m.id === missionId ? { ...m, ...patch } : m))
    setStationMissions(stationId, next)
  }

  /**
   * โหลดด่านย่อยของฐานนี้จาก Backend (action 'getStationMissions' — ฝั่งผู้เล่น
   * sanitized เท่านั้น ไม่ใช่ 'listStationMissions' ที่เป็น Admin-only) ต้องมี
   * internet เสมอตอนโหลดครั้งแรก ยิงไม่สำเร็จ -> ใช้ Cache ล่าสุดที่มีอยู่ต่อไปได้
   * (คืน true ถ้ามี Cache ให้แสดงอยู่แล้ว)
   */
  async function loadStationMissions(
    stationId: string,
    roundId: string | null,
    userId: string | undefined,
  ): Promise<boolean> {
    if (!import.meta.client) return false

    isLoading.value = true
    loadError.value = ''
    try {
      const { getStationMissions: fetchStationMissions } = useMemberApi()
      const res = await fetchStationMissions(stationId, roundId ?? undefined, userId)
      if (res.success && res.missions) {
        setStationMissions(stationId, res.missions)
        return true
      }
      loadError.value = res.error || 'โหลดด่านย่อยของฐานนี้ไม่สำเร็จ'
      return getStationMissions(stationId).length > 0
    } catch {
      loadError.value =
        'ไม่สามารถโหลดด่านย่อยของฐานนี้ได้ในขณะนี้ (ไม่มีอินเทอร์เน็ต หรือ Backend ไม่ตอบสนอง)'
      return getStationMissions(stationId).length > 0
    } finally {
      isLoading.value = false
    }
  }

  /** ด่านประเภท SINGLE_QUESTION — ส่ง index ของตัวเลือกที่เลือกไปให้ Backend ตัดสิน
   * ทันที (Backend ไม่ส่ง correctAnswer มาให้ฝั่งนี้เลย จึงตัดสินเองไม่ได้) มีเน็ต
   * -> รู้ผลจริงทันที ไม่มีเน็ต -> queue ไว้รอ sync (pending: true, ยังไม่ mark
   * completed จนกว่าจะรู้ผลจริง) */
  async function submitSingleQuestion(
    stationId: string,
    mission: StationMission,
    answerIndex: number,
    ctx: { userId: string; roundId: string | null },
  ): Promise<MissionSubmitOutcome> {
    try {
      const { submitMissionAnswer } = useMemberApi()
      const res = await submitMissionAnswer({
        missionId: mission.id,
        roundId: ctx.roundId ?? '',
        userId: ctx.userId,
        answer: answerIndex,
      })
      if (!res.success) {
        return {
          pending: false,
          correct: false,
          pointsAwarded: 0,
          alreadyCompleted: false,
          error: res.error || 'ส่งคำตอบไม่สำเร็จ กรุณาลองใหม่',
        }
      }
      const correct = !!res.correct
      const pointsAwarded = res.pointsAwarded ?? 0
      if (correct) {
        updateMissionFromResult(stationId, mission.id, { completed: true })
      }
      return {
        pending: false,
        correct,
        pointsAwarded,
        alreadyCompleted: !!res.alreadyCompleted,
      }
    } catch {
      const { queueMissionAnswer } = useOfflineMissionAnswerSync()
      queueMissionAnswer({
        kind: 'single',
        stationId,
        missionId: mission.id,
        roundId: ctx.roundId,
        userId: ctx.userId,
        answer: answerIndex,
      })
      return { pending: true, correct: false, pointsAwarded: 0, alreadyCompleted: false }
    }
  }

  /** ด่านประเภท MULTI_QUESTION — ส่ง array ของ index ไปให้ Backend ตัดสินทีเดียว
   * (ตำแหน่งต้องตรงกับ mission.questions[] เป๊ะ) เหมือน submitSingleQuestion —
   * ไม่มีเน็ต -> queue ไว้รอ sync */
  async function submitMultiQuestion(
    stationId: string,
    mission: StationMission,
    answers: number[],
    ctx: { userId: string; roundId: string | null },
  ): Promise<MissionSubmitOutcome> {
    try {
      const { submitMultiMission } = useMemberApi()
      const res = await submitMultiMission({
        missionId: mission.id,
        roundId: ctx.roundId ?? '',
        userId: ctx.userId,
        answers,
      })
      if (!res.success) {
        return {
          pending: false,
          correct: false,
          pointsAwarded: 0,
          alreadyCompleted: false,
          error: res.error || 'ส่งคำตอบไม่สำเร็จ กรุณาลองใหม่',
        }
      }
      const passed = !!res.passed
      const pointsAwarded = res.pointsAwarded ?? 0
      if (passed) {
        updateMissionFromResult(stationId, mission.id, { completed: true })
      }
      return {
        pending: false,
        correct: passed,
        correctCount: res.correctCount,
        totalQuestions: res.totalQuestions,
        pointsAwarded,
        alreadyCompleted: !!res.alreadyCompleted,
      }
    } catch {
      const { queueMissionAnswer } = useOfflineMissionAnswerSync()
      queueMissionAnswer({
        kind: 'multi',
        stationId,
        missionId: mission.id,
        roundId: ctx.roundId,
        userId: ctx.userId,
        answers,
      })
      return { pending: true, correct: false, pointsAwarded: 0, alreadyCompleted: false }
    }
  }

  /**
   * ด่านประเภท QR_SCORE — ตรวจสอบ QR ของด่าน (คนละ QR/handler กับ
   * verifyStationQr เด็ดขาด — ดู types/mission.ts) ต้องมีอินเทอร์เน็ตเสมอ ไม่มี
   * Offline Fallback (เหมือน verifyStationQr) ผ่านแล้ว Backend ให้คะแนนจริงทันที
   */
  async function verifyQrMission(
    stationId: string,
    mission: StationMission,
    qrToken: string,
    ctx: { userId: string; roundId: string },
  ): Promise<{ success: boolean; pointsEarned: number; error?: string }> {
    const { verifyMissionQr } = useMemberApi()
    try {
      const res = await verifyMissionQr({ qrToken, roundId: ctx.roundId, userId: ctx.userId })
      if (!res.success) {
        return { success: false, pointsEarned: 0, error: res.error || 'QR ด่านนี้ไม่ถูกต้อง' }
      }
      const pointsEarned = res.pointsAwarded ?? 0
      updateMissionFromResult(stationId, mission.id, { completed: true })
      return { success: true, pointsEarned }
    } catch (err) {
      return {
        success: false,
        pointsEarned: 0,
        error:
          err instanceof Error
            ? err.message
            : 'ตรวจสอบ QR กับระบบไม่สำเร็จ กรุณาตรวจสอบอินเทอร์เน็ตแล้วลองใหม่',
      }
    }
  }

  return {
    isLoading: readonly(isLoading),
    loadError: readonly(loadError),
    totalPointsEarned,
    getStationMissions,
    missionProgressCount,
    isStationMissionComplete,
    initStationMissions,
    loadStationMissions,
    submitSingleQuestion,
    submitMultiQuestion,
    verifyQrMission,
  }
}
